std::vector<int> nums = {1, 2, 3, 4, 5};
std::vector<int> squares(nums.size());

// Transformation: Apply function to every element
std::transform(nums.begin(), nums.end(), squares.begin(),
    [](int x) { return x * x; });

// squares is now {1, 4, 9, 16, 25}

// Avoids manual loops and temporary variable management
// Precondition: squares must be correctly sized or use a back_inserter

std::vector<int> data = {5, 20, 15, 30, 8};

// Conditional Search: Find first element satisfying predicate
auto it = std::find_if(data.begin(), data.end(),
    [](int x) { return x > 25; });

if (it != data.end()) {
    // Found 30
}

// Counting: Count elements meeting criteria
long passing_score = std::count_if(data.begin(), data.end(),
    [](int x) { return x >= 15; });
// passing_score = 3

std::vector<int> duplicates = {3, 1, 4, 1, 5, 9, 3};

// Modification: Sort and Remove Duplicates (Requires Sorting)
std::sort(duplicates.begin(), duplicates.end());
// {1, 1, 3, 3, 4, 5, 9}

// unique moves non-duplicates to front, returns iterator to new end
auto new_end = std::unique(duplicates.begin(), duplicates.end());

// Physical removal of excess elements
duplicates.erase(new_end, duplicates.end());
// {1, 3, 4, 5, 9}

std::vector<int> series(5);

// Generation: Fill with sequential values starting at 50
std::iota(series.begin(), series.end(), 50);
// {50, 51, 52, 53, 54}

// Generation: Fill with same value
std::fill(series.begin(), series.end(), -1);
// {-1, -1, -1, -1, -1}
